class OrderAdapter
  def initialize(url, exchange = "orders")
    @conn = Bunny.new(url).tap(&:start)
    @ch = @conn.create_channel
    @x = @ch.topic(exchange, durable: true)
  end
  def publish(order) = @x.publish(order.to_json, routing_key: "order.placed", persistent: true)
  def subscribe(&handler)
    @ch.queue("orders", durable: true).bind(@x).subscribe do |_info, _props, payload|
      handler.call(JSON.parse(payload))
    end
  end
end
